function hackerNewsSnapshot({ body, statusCode, bodyEncoding = null }) {
  if (statusCode !== 200) throw new Error("Hacker News search did not return HTTP 200.");
  if (bodyEncoding !== null) throw new Error("Expected a JSON search response.");
  if (!body || typeof body !== "object" || Array.isArray(body) || !Array.isArray(body.hits))
    throw new Error("The search response must contain a hits array.");
  if (body.hits.length > 50)
    throw new Error("The search returned more than the requested fifty items.");
  const text = (value, name) => {
    if (value === null || value === undefined) return null;
    if (typeof value !== "string") throw new Error("Invalid " + name + " in search result.");
    return value;
  };
  const items = body.hits.map((hit) => {
    if (!hit || typeof hit !== "object" || Array.isArray(hit))
      throw new Error("Invalid search item.");
    if (
      hit.points !== null &&
      hit.points !== undefined &&
      (typeof hit.points !== "number" || !Number.isFinite(hit.points))
    )
      throw new Error("Invalid points in search result.");
    return {
      title: text(hit.title, "title"),
      points: hit.points ?? null,
      url: text(hit.url, "url"),
      created_at: text(hit.created_at, "created_at"),
      author: text(hit.author, "author"),
    };
  });
  return { response: JSON.stringify(items), count: items.length };
}

const result = hackerNewsSnapshot({ ...$input.first().json, bodyEncoding: null });
return [{ json: result }];
